1	import initSqlJs, { Database, SqlJsStatic } from 'sql.js';
2	import { readFileSync, existsSync, writeFileSync } from 'fs';
3	import { join, dirname } from 'path';
4	import { fileURLToPath } from 'url';
5	
6	const __filename = fileURLToPath(import.meta.url);
7	const __dirname = dirname(__filename);
8	
9	let SQL: SqlJsStatic;
10	let db: Database;
11	let dbPath: string;
12	
13	export async function initDb(path?: string): Promise<Database> {
14	  if (!SQL) {
15	    SQL = await initSqlJs({
16	      locateFile: (file: string) => join(__dirname, '..', '..', 'node_modules', 'sql.js', 'dist', file)
17	    });
18	  }
19	
20	  dbPath = path || join(process.cwd(), 'bookshelf.db');
21	
22	  if (existsSync(dbPath)) {
23	    const buffer = readFileSync(dbPath);
24	    db = new SQL.Database(buffer);
25	  } else {
26	    db = new SQL.Database();
27	  }
28	
29	  db.run('PRAGMA foreign_keys = ON');
30	
31	  const schema = readFileSync(join(__dirname, 'schema.sql'), 'utf-8');
32	  db.run(schema);
33	
34	  const userCount = db.exec('SELECT COUNT(*) as count FROM users');
35	  const count = userCount.length > 0 ? userCount[0].values[0][0] : 0;
36	
37	  if (count === 0) {
38	    const seed = readFileSync(join(__dirname, 'seed.sql'), 'utf-8');
39	    db.run(seed);
40	  }
41	
42	  saveDb();
43	  return db;
44	}
45	
46	export function getDb(): Database {
47	  if (!db) {
48	    throw new Error('Database not initialized. Call initDb() first.');
49	  }
50	  return db;
51	}
52	
53	export function saveDb(): void {
54	  if (db) {
55	    const data = db.export();
56	    const buffer = Buffer.from(data);
57	    writeFileSync(dbPath, buffer);
58	  }
59	}
60	
61	export function closeDb(): void {
62	  if (db) {
63	    saveDb();
64	    db.close();
65	  }
66	}
67	
68	export function query(sql: string, params: unknown[] = []): { columns: string[]; values: unknown[][] }[] {
69	  return getDb().exec(sql, params as any);
70	}
71	
72	export function get(sql: string, params: unknown[] = []): Record<string, unknown> | undefined {
73	  const stmt = getDb().prepare(sql);
74	  stmt.bind(params as any);
75	  if (stmt.step()) {
76	    const row = stmt.getAsObject();
77	    stmt.free();
78	    return row as Record<string, unknown>;
79	  }
80	  stmt.free();
81	  return undefined;
82	}
83	
84	export function all(sql: string, params: unknown[] = []): Record<string, unknown>[] {
85	  const stmt = getDb().prepare(sql);
86	  stmt.bind(params as any);
87	  const results: Record<string, unknown>[] = [];
88	  while (stmt.step()) {
89	    results.push(stmt.getAsObject() as Record<string, unknown>);
90	  }
91	  stmt.free();
92	  return results;
93	}
94	
95	export function run(sql: string, params: unknown[] = []): { changes: number; lastInsertRowid: number } {
96	  getDb().run(sql, params as any);
97	  const changesResult = getDb().exec('SELECT changes() as changes, last_insert_rowid() as lastInsertRowid');
98	  const changes = changesResult[0]?.values[0][0] as number || 0;
99	  const lastInsertRowid = changesResult[0]?.values[0][1] as number || 0;
100	  return { changes, lastInsertRowid };
101	}
